-- KBS한국어능력시험 모의고사 1회 (program=kbs, year=2025, round=1, 100문항)
-- 오리지널 창작(저작권 안전). 듣기(1~15)는 audio_url 음성. 선행: 026,028.
-- Supabase SQL Editor에서 실행.
DELETE FROM public.questions WHERE program='kbs' AND year=2025 AND round=1;
INSERT INTO public.questions (program,year,round,number,type,question,options,correct_answer,explanation,points,passage,audio_url) VALUES
('kbs',2025,1,1,'multiple','[듣기] 강연을 잘 듣고, 강연자가 말하고자 하는 바로 가장 알맞은 것을 고르십시오.','["직업 이름은 예전 방식대로 불러야 한다.", "말의 변화에는 그 사회의 생각이 담겨 있다.", "성별을 드러내는 표현이 더 정확하다.", "말은 시대와 상관없이 늘 같아야 한다.", "새로운 표현은 혼란만 일으킨다."]'::jsonb,'2','강연자는 직업 명칭의 변화를 예로 들어, 말을 다듬는 일이 곧 생각을 다듬는 일이며 말에는 사회의 생각이 반영된다고 말한다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-1.mp3'),
('kbs',2025,1,2,'multiple','[듣기] 이야기를 잘 듣고, 이 이야기가 주는 교훈으로 가장 알맞은 것을 고르십시오.','["부지런하면 복이 온다.", "친구는 많을수록 좋다.", "달콤한 칭찬에 넘어가면 손해를 본다.", "노래 실력을 길러야 한다.", "위험할 때는 도망쳐야 한다."]'::jsonb,'3','여우의 아첨에 우쭐해진 까마귀가 입을 벌리다 치즈를 빼앗긴다. 근거 없는 칭찬에 흔들리면 손해를 본다는 교훈이다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-2.mp3'),
('kbs',2025,1,3,'multiple','[듣기] 시를 잘 듣고, 이 시의 분위기로 가장 알맞은 것을 고르십시오.','["시끄럽고 분주하다.", "맑고 고요하다.", "어둡고 무섭다.", "슬프고 절망적이다.", "우스꽝스럽다."]'::jsonb,'2','밤새 내린 눈, 아무도 밟지 않은 마당, 조용히 내려앉는 햇살, 하얀 고요 등의 심상이 맑고 고요한 분위기를 자아낸다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-3.mp3'),
('kbs',2025,1,4,'multiple','[듣기] 안내 방송을 잘 듣고, 방송 내용과 일치하는 것을 고르십시오.','["도서관 전체가 문을 닫는다.", "삼 층 열람실을 오후에 이용할 수 없다.", "점검은 오전에 끝난다.", "일 층 열람실도 점검 중이다.", "자료 열람은 아예 불가능하다."]'::jsonb,'2','오후 두 시부터 다섯 시까지 삼 층 열람실만 점검으로 이용할 수 없고, 일 층 일반 열람실은 이용할 수 있다고 안내한다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-4.mp3'),
('kbs',2025,1,5,'multiple','[듣기] 대화를 잘 듣고, 두 사람의 대화에 대한 설명으로 알맞은 것을 고르십시오.','["남자는 처음부터 부분 환불을 요구했다.", "여자는 남자의 요구를 그대로 받아들였다.", "남자는 여자의 제안을 조정해 다시 제안했다.", "여자는 배송 지연을 인정하지 않았다.", "두 사람은 합의하지 못하고 끝냈다."]'::jsonb,'3','남자는 처음엔 전액 환불을 요구했으나, 여자의 절충안을 듣고 결제 금액 일부 환불로 조정해 다시 제안했다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-5.mp3'),
('kbs',2025,1,6,'multiple','[듣기] 대화를 잘 듣고, 남자의 의도로 가장 알맞은 것을 고르십시오.','["등산을 취소하려 한다.", "비가 와도 토요일에 가려 한다.", "일요일에 일찍 출발하자고 제안한다.", "여자와 따로 가려 한다.", "등산 대신 다른 곳에 가려 한다."]'::jsonb,'3','남자는 토요일 비 예보를 근거로 일요일로 미루는 데 동의하며, 사람이 많아지기 전에 아침 일찍 출발하자고 제안한다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-6.mp3'),
('kbs',2025,1,7,'multiple','[듣기] 일기 예보를 잘 듣고, 방송 내용과 일치하는 것을 고르십시오.','["내일 아침부터 전국에 비가 온다.", "오후 늦게 수도권에 비가 지나갈 수 있다.", "기온이 어제보다 크게 오른다.", "하루 종일 흐리고 비가 온다.", "동쪽 지방부터 구름이 많아진다."]'::jsonb,'2','내일 낮부터 서쪽을 중심으로 구름이 많아지고, 오후 늦게 수도권·충청에 약한 비가 지나갈 수 있다고 했다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-7.mp3'),
('kbs',2025,1,8,'multiple','[듣기] 강연을 잘 듣고, 강연의 중심 내용으로 알맞은 것을 고르십시오.','["꿀벌은 꿀을 모으는 곤충일 뿐이다.", "꿀벌의 꽃가루받이가 작물 생산에 중요하다.", "과일은 꿀벌 없이도 잘 자란다.", "곤충은 우리 식탁과 관련이 없다.", "꿀벌은 꽃을 해친다."]'::jsonb,'2','강연자는 꿀벌의 꽃가루받이가 과일·채소의 열매 맺기에 필수적이어서 작물 생산과 깊이 연결된다고 말한다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-8.mp3'),
('kbs',2025,1,9,'multiple','[듣기] 면접 대화를 잘 듣고, 지원자의 답변 태도로 알맞은 것을 고르십시오.','["회사보다 개인의 이익을 앞세운다.", "질문에 어긋난 답을 한다.", "지원 동기와 포부를 구체적으로 밝힌다.", "답변을 회피한다.", "면접관에게 질문만 한다."]'::jsonb,'3','지원자는 지원 동기(도움이 되는 서비스)와 입사 후 포부(사용자 의견 반영)를 구체적으로 밝힌다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-9.mp3'),
('kbs',2025,1,10,'multiple','[듣기] 대화를 잘 듣고, 대화 내용과 일치하는 것을 고르십시오.','["여자는 남자의 도움을 거절했다.", "남자가 토요일 아침에 도우러 간다.", "두 사람은 일요일에 만나기로 했다.", "여자가 아침을 사기로 했다.", "남자가 이사를 한다."]'::jsonb,'2','남자가 토요일 아침에 이사를 도우러 가고 아침을 사 가기로 했으며, 여자는 점심을 사기로 했다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-10.mp3'),
('kbs',2025,1,11,'multiple','[듣기] 대화를 잘 듣고, 대화에 대한 설명으로 알맞은 것을 고르십시오.','["학생은 처음부터 이틀만 요구했다.", "담당자는 요구를 전부 거절했다.", "학생이 요구를 줄여 절충안을 냈고 담당자가 조건부로 수용했다.", "두 사람은 합의하지 못했다.", "담당자가 매일 사용을 허락했다."]'::jsonb,'3','학생은 평일 저녁 매일에서 화·목 이틀로 요구를 줄였고, 담당자는 사용 후 정리를 조건으로 수용했다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-11.mp3'),
('kbs',2025,1,12,'multiple','[듣기] 이야기를 잘 듣고, 이 이야기의 교훈으로 알맞은 것을 고르십시오.','["부지런히 일해야 한다.", "지나친 욕심을 경계해야 한다.", "여행은 위험하다.", "돈을 아껴 써야 한다.", "남을 함부로 믿지 말아야 한다."]'::jsonb,'2','방값으로 큰돈을 요구한 부자에게 나그네가 그림자 값을 내겠다고 하자 부자가 부끄러워한다. 지나친 욕심을 경계하라는 교훈이다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-12.mp3'),
('kbs',2025,1,13,'multiple','[듣기] 발표를 잘 듣고, 발표자가 전하려는 바로 알맞은 것을 고르십시오.','["재활용은 번거로워 실패했다.", "작은 실천이 모이면 큰 변화가 된다.", "종이는 재활용할 수 없다.", "쓰레기는 전혀 줄지 않았다.", "재활용은 습관이 될 수 없다."]'::jsonb,'2','한 달간의 분리배출로 쓰레기의 절반을 재활용했고, 작은 실천이 모이면 큰 변화가 된다는 것을 배웠다고 발표한다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-13.mp3'),
('kbs',2025,1,14,'multiple','[듣기] 강연을 잘 듣고, 강연자가 권하는 것으로 알맞은 것을 고르십시오.','["말을 많이 하라.", "말하기 전에 한 번 더 생각하라.", "빚을 갚아라.", "되도록 침묵하라.", "속담을 외워라."]'::jsonb,'2','강연자는 말은 주워 담을 수 없으니 상대를 배려해 말하기 전에 한 번 더 생각하는 습관을 들이자고 권한다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-14.mp3'),
('kbs',2025,1,15,'multiple','[듣기] 안내 대화를 잘 듣고, 안내 내용과 일치하는 것을 고르십시오.','["입장은 여섯 시 삼십 분까지 가능하다.", "모든 작품을 촬영할 수 있다.", "플래시를 켜고 촬영해도 된다.", "일부 작품은 촬영이 금지된다.", "관람은 오후 다섯 시까지다."]'::jsonb,'4','입장은 여섯 시, 관람은 여섯 시 삼십 분까지이며, 플래시 없이 촬영 가능하되 일부 작품은 촬영이 금지된다.',10,NULL,'https://itzhfbsbwuoedncnjhzt.supabase.co/storage/v1/object/public/question-assets/listening/kbs-2025-1-15.mp3'),
('kbs',2025,1,16,'multiple','다음 중 고유어와 그 뜻풀이가 바르게 연결된 것은?','["미주알: 물건의 가장 아랫부분", "마수걸이: 하루 일을 끝낸 뒤에 갖는 첫 휴식", "고샅: 시골 마을의 좁은 골목길", "곰비임비: 어쩌다가 아주 가끔", "애면글면: 남을 원망하며 투덜대는 모양"]'::jsonb,'3','''고샅''은 시골 마을의 좁은 골목길을 뜻하므로 바르게 연결되었다. ''미주알''은 항문을 이루는 창자의 끝부분, ''마수걸이''는 맨 처음으로 물건을 파는 일이나 그 이익, ''곰비임비''는 물건이 거듭 쌓이거나 일이 계속 일어나는 모양, ''애면글면''은 몹시 힘에 겨운 일을 이루려고 갖은 애를 쓰는 모양을 뜻한다.',10,NULL,NULL),
('kbs',2025,1,17,'multiple','다음 문장에서 밑줄 친 ''그늘''의 문맥적 의미로 가장 알맞은 것은?

그는 부모님의 그늘 아래서 부족함 없이 자랐다.','["빛이 가려져 어두워진 부분", "밖으로 잘 드러나지 않는 처지나 형편", "근심이나 불행으로 어두워진 마음", "의지할 만한 대상의 보호나 혜택", "남에게 알리고 싶지 않은 부끄러운 과거"]'::jsonb,'4','''부모님의 그늘 아래서 자랐다''에서 ''그늘''은 의지할 만한 대상의 보호나 혜택을 뜻한다. 나머지도 모두 ''그늘''의 사전적 의미에 해당하지만, 주어진 문맥에서는 보호와 혜택의 뜻으로 쓰였다.',10,NULL,NULL),
('kbs',2025,1,18,'multiple','다음 문장에서 밑줄 친 한자어 ''괴리(乖離)''의 뜻으로 알맞은 것은?

이상과 현실 사이의 괴리가 갈수록 커졌다.','["서로 어울려 하나가 됨", "서로 어그러져 동떨어짐", "점점 가까워져 간격이 좁혀짐", "자연스럽게 이어져 연결됨", "정도가 서로 비슷하게 맞아떨어짐"]'::jsonb,'2','''괴리(乖離)''는 ''서로 어그러져 동떨어짐''을 뜻하는 한자어이다. 이상과 현실이 서로 맞지 않고 벌어져 있음을 나타낸다.',10,NULL,NULL),
('kbs',2025,1,19,'multiple','다음 상황을 나타내기에 가장 알맞은 한자성어는?

당장의 작은 이익에 눈이 멀어 도리어 더 큰 것을 잃고 마는 어리석음.','["견물생심(見物生心)", "소탐대실(小貪大失)", "대기만성(大器晩成)", "청출어람(靑出於藍)", "괄목상대(刮目相對)"]'::jsonb,'2','''소탐대실(小貪大失)''은 작은 것을 탐하다가 큰 것을 잃는다는 뜻으로 제시된 상황에 가장 알맞다. ''견물생심''은 물건을 보면 욕심이 생김, ''대기만성''은 큰 인물이 늦게 이루어짐, ''청출어람''은 제자가 스승보다 나음, ''괄목상대''는 실력이 크게 늘어 다시 보게 됨을 뜻한다.',10,NULL,NULL),
('kbs',2025,1,20,'multiple','다음 뜻풀이에 해당하는 속담으로 알맞은 것은?

아무리 익숙하고 잘하는 사람도 때로는 실수할 수 있다.','["우물에서 숭늉 찾는다", "낫 놓고 기역 자도 모른다", "빈 수레가 요란하다", "원숭이도 나무에서 떨어진다", "등잔 밑이 어둡다"]'::jsonb,'4','''원숭이도 나무에서 떨어진다''는 아무리 능숙한 사람도 실수할 때가 있음을 이르는 속담이다. ''우물에서 숭늉 찾는다''는 성급함, ''낫 놓고 기역 자도 모른다''는 아주 무식함, ''빈 수레가 요란하다''는 실속 없이 떠벌림, ''등잔 밑이 어둡다''는 가까이 있는 것을 오히려 잘 모름을 뜻한다.',10,NULL,NULL),
('kbs',2025,1,21,'multiple','다음 문장에서 밑줄 친 관용구 ''발 벗고 나서다''의 뜻으로 알맞은 것은?

그 문제라면 내가 발 벗고 나서서 도와주겠네.','["마지못해 억지로 참여함", "남몰래 슬그머니 빠져나감", "적극적으로 나서서 일을 함", "이것저것 재며 몹시 망설임", "책임을 남에게 슬쩍 떠넘김"]'::jsonb,'3','''발 벗고 나서다''는 어떤 일에 적극적으로 나서서 힘씀을 뜻하는 관용구이다.',10,NULL,NULL),
('kbs',2025,1,22,'multiple','밑줄 친 ''먹다''가 다음 문장의 ''먹다''와 같은 의미로 쓰인 것은?

그는 크게 겁을 먹고 아무 말도 하지 못했다.','["아침을 든든히 먹고 길을 나섰다.", "그는 굳게 마음을 먹고 도전에 임했다.", "이 낡은 자동차는 기름을 많이 먹는다.", "그는 나이가 들면서 귀가 먹어 잘 듣지 못한다.", "이번 시합에서 우리 편이 먼저 한 골을 먹었다."]'::jsonb,'2','제시문의 ''겁을 먹다''와 선택지 2의 ''마음을 먹다''는 모두 ''어떤 마음이나 감정을 품다''라는 의미로 쓰인 다의어이다. 1은 음식을 섭취하다, 3은 연료 따위를 소비하다, 4는 감각 기능이 제 기능을 하지 못하다, 5는 점수나 골을 잃다의 뜻이다.',10,NULL,NULL),
('kbs',2025,1,23,'multiple','밑줄 친 두 단어의 의미 관계가 나머지 넷과 다른 것은?','["머리를 짧게 잘랐다 / 그는 머리가 비상하다", "의자의 다리가 부러졌다 / 오래 걸어 다리가 아프다", "어두운 밤이 깊었다 / 가을이라 밤이 잘 여문다", "그는 손이 큰 사람이다 / 바빠서 일할 손이 모자란다", "강물이 깊게 흐른다 / 어느새 세월이 흘렀다"]'::jsonb,'3','3의 ''밤''은 각각 ''해가 진 뒤의 밤(night)''과 ''밤나무의 열매(chestnut)''로, 소리는 같지만 의미가 전혀 다른 동음이의어이다. 나머지는 하나의 단어가 관련된 여러 의미로 확장되어 쓰인 다의어 관계이다.',10,NULL,NULL),
('kbs',2025,1,24,'multiple','밑줄 친 단어와 바꾸어 쓸 수 있는 것은?

그는 매사에 신중한 사람이다.','["대범한", "조심스러운", "성급한", "경솔한", "무모한"]'::jsonb,'2','''신중하다''는 매우 조심스럽다는 뜻이므로 ''조심스러운''과 유의 관계에 있어 바꾸어 쓸 수 있다. ''성급한, 경솔한, 무모한''은 오히려 반대되는 의미이며, ''대범한''은 사소한 것에 얽매이지 않는다는 뜻으로 의미가 다르다.',10,NULL,NULL),
('kbs',2025,1,25,'multiple','다음 중 두 단어의 의미 관계가 나머지와 다른 것은?','["낙관 - 비관", "가결 - 부결", "곤궁 - 궁핍", "굴복 - 저항", "응축 - 팽창"]'::jsonb,'3','''곤궁(困窮)''과 ''궁핍(窮乏)''은 모두 가난하고 어려운 상태를 뜻하는 유의 관계이다. 나머지 ''낙관-비관'', ''가결-부결'', ''굴복-저항'', ''응축-팽창''은 모두 서로 반대되는 뜻의 반의 관계이다.',10,NULL,NULL),
('kbs',2025,1,26,'multiple','다음 중 앞의 말이 상의어, 뒤의 말이 하의어인 관계로 짝지어진 것은?','["바퀴 - 자동차", "여름 - 겨울", "의사 - 간호사", "악기 - 첼로", "연필 - 지우개"]'::jsonb,'4','''악기''는 ''첼로''를 포함하는 상의어이고 ''첼로''는 그에 속하는 하의어이므로 상하 관계이다. ''바퀴-자동차''는 부분과 전체 관계, ''여름-겨울''은 반의(대립) 관계, ''의사-간호사''와 ''연필-지우개''는 서로 대등한 관계이다.',10,NULL,NULL),
('kbs',2025,1,27,'multiple','밑줄 친 고유어를 한자어로 바꾼 것으로 가장 알맞은 것은?

회사는 회의 날짜를 뒤로 미루었다.','["취소(取消)하였다", "단축(短縮)하였다", "연기(延期)하였다", "확정(確定)하였다", "반복(反復)하였다"]'::jsonb,'3','''날짜를 뒤로 미루다''는 예정된 때를 뒤로 물린다는 뜻이므로 한자어 ''연기(延期)하다''로 바꾸어 쓸 수 있다. ''취소''는 없던 것으로 함, ''단축''은 짧게 줄임, ''확정''은 확실히 정함, ''반복''은 되풀이함을 뜻한다.',10,NULL,NULL),
('kbs',2025,1,28,'multiple','다음 중 한자어와 그 순화어(다듬은 말)의 연결이 바르지 않은 것은?','["익일(翌日) → 다음 날", "노견(路肩) → 갓길", "잔고(殘高) → 잔돈", "절수(節水) → 물 아낌", "하시(何時) → 언제"]'::jsonb,'3','''잔고(殘高)''는 나머지 액수, 곧 ''남은 금액(잔액)''을 뜻하므로 ''잔돈''으로 다듬는 것은 바르지 않다. ''잔돈''은 단위가 작은 돈이나 거스름돈을 가리켜 의미가 다르다. 나머지는 모두 바르게 순화되었다.',10,NULL,NULL),
('kbs',2025,1,29,'multiple','다음 중 외래어와 그 순화어(다듬은 말)의 연결이 바르지 않은 것은?','["리플(reply) → 댓글", "스크린 도어 → 안전문", "내비게이션 → 길도우미", "마일리지 → 이용 실적", "로드맵(road map) → 지름길"]'::jsonb,'5','''로드맵''은 앞으로 나아갈 단계별 계획이나 방향을 뜻하므로 ''이정표'' 또는 ''단계별 계획''으로 다듬는 것이 알맞다. ''지름길''은 빨리 가는 길(shortcut)을 뜻하여 의미가 다르다. 나머지는 모두 바르게 순화되었다.',10,NULL,NULL),
('kbs',2025,1,30,'multiple','밑줄 친 한자성어의 쓰임이 문맥에 어울리지 않는 것은?','["그는 일취월장(日就月將)하여 실력이 몰라보게 늘었다.", "두 회사는 순망치한(脣亡齒寒)의 관계라 한쪽이 무너지면 다른 쪽도 위태롭다.", "아무 준비 없이 시작했다가 낭패를 보았으니 그야말로 유비무환(有備無患)이다.", "사소한 다툼이 일파만파(一波萬波)로 번져 큰 싸움이 되었다.", "오랜 노력 끝에 고진감래(苦盡甘來), 마침내 값진 결실을 보았다."]'::jsonb,'3','''유비무환(有備無患)''은 미리 준비가 되어 있으면 걱정할 것이 없다는 뜻이다. 준비 없이 시작하여 낭패를 본 상황과는 오히려 반대되므로 쓰임이 어울리지 않는다. 나머지는 모두 문맥에 알맞게 쓰였다.',10,NULL,NULL),
('kbs',2025,1,31,'multiple','다음 중 밑줄 친 단어의 표준 발음이 옳지 않은 것은?','["닭이[달기] 우니 새벽이 밝아 온다.", "여덟[여덜] 명이 함께 길을 나섰다.", "그는 자리에 앉다[안따] 말고 벌떡 일어섰다.", "하늘이 맑고[막꼬] 바람이 시원하다.", "강아지가 손등을 핥다[할따] 잠이 들었다."]'::jsonb,'4','용언 어간의 겹받침 ''ㄺ''은 자음 ''ㄱ'' 앞에서 [ㄹ]로 발음하므로 ''맑고''는 [말꼬]로 소리 난다. [막꼬]는 틀린 발음이다. ''닭이''는 겹받침이 모음 조사와 만나 연음되어 [달기], ''여덟''은 [여덜], ''앉다''는 [안따], ''핥다''는 [할따]로 모두 옳다.',10,NULL,NULL),
('kbs',2025,1,32,'multiple','다음 중 밑줄 친 부분의 맞춤법이 옳은 것은?','["이번 일이 잘 됬으면 참 좋겠다.", "어제 산 옷이 마음에 드러서 자주 입는다.", "그는 끝까지 아는 체도 하지 않았다.", "밥을 먹던지 말던지 네 마음대로 해라.", "나갈 때 현관문을 꼭 잠구고 나왔다."]'::jsonb,'3','''아는 체''의 ''체''는 ''그럴듯하게 꾸미는 거짓 태도''를 뜻하는 의존 명사로 바르게 쓰였다. 나머지는 ''됐으면(되었으면)'', ''들어서'', ''먹든지 말든지(선택은 ''-든지'')'', ''잠그고''로 고쳐야 한다.',10,NULL,NULL),
('kbs',2025,1,33,'multiple','다음 중 띄어쓰기가 옳은 것은?','["십 년 만에 고향 마을에 돌아왔다.", "그가 떠난지 벌써 한 달이 지났다.", "우리는 아는것이 힘이라고 배웠다.", "이 세상에 너 밖에 없는 것 같다.", "회의실에 김철수씨가 먼저 와 있었다."]'::jsonb,'1','''만''이 ''시간의 경과''를 나타낼 때는 의존 명사이므로 ''십 년 만에''처럼 띄어 쓴다. 나머지는 ''떠난 지(의존 명사 ''지'')'', ''아는 것이(의존 명사 ''것'')'', ''너밖에(조사 ''밖에''는 붙임)'', ''김철수 씨(호칭 ''씨''는 띄어 씀)''로 고쳐야 한다.',10,NULL,NULL),
('kbs',2025,1,34,'multiple','다음 중 문장 부호의 사용이 옳지 않은 것은?','["아버지께서는 \"시간을 아껴라.\"라고 늘 말씀하셨다.", "이번 결승전은 3:2로 우리 팀의 승리로 끝났다.", "다음 회의 시간은 오후 2 : 30이다.", "장을 보아 사과, 배, 감을 한 봉지씩 샀다.", "그가 밤새 읽은 책의 제목은 『토지』이다."]'::jsonb,'3','시(時)와 분(分)을 나타낼 때 쓰는 쌍점(:)은 앞뒤를 붙여 써야 하므로 ''오후 2:30''이 옳다. ''2 : 30''처럼 앞뒤를 띄운 것은 잘못이다. 직접 인용의 큰따옴표, 비율의 쌍점(3:2), 열거의 쉼표, 책 제목의 겹낫표는 모두 바르게 쓰였다.',10,NULL,NULL),
('kbs',2025,1,35,'multiple','다음 중 표준어가 아닌 것은?','["강낭콩", "웃어른", "미장이", "사글세", "아지랭이"]'::jsonb,'5','''ㅣ'' 역행 동화가 인정되지 않아 표준어는 ''아지랑이''이며 ''아지랭이''는 비표준어이다. ''강낭콩'', ''웃어른'', ''미장이'', ''사글세''는 모두 표준어 규정에 맞는 표준어이다.',10,NULL,NULL),
('kbs',2025,1,36,'multiple','다음 중 외래어 표기법에 맞는 것은?','["초콜렛", "소세지", "액세서리", "플래쉬", "앵콜"]'::jsonb,'3','외래어 표기법에 따른 바른 표기는 ''accessory → 액세서리''이다. 나머지는 각각 ''초콜릿'', ''소시지'', ''플래시'', ''앙코르''로 적어야 한다.',10,NULL,NULL),
('kbs',2025,1,37,'multiple','다음 중 국어의 로마자 표기가 옳은 것은?','["종로 - Jongro", "신라 - Sinla", "부산 - Pusan", "백마 - Baekma", "왕십리 - Wangsimni"]'::jsonb,'5','로마자 표기는 표준 발음을 따르므로 ''왕십리[왕심니]''는 자음 동화를 반영해 ''Wangsimni''로 적는 것이 옳다. 나머지는 ''종로[종노] Jongno'', ''신라[실라] Silla'', ''부산 Busan(어두의 ''ㅂ''은 b)'', ''백마[뱅마] Baengma''로 적어야 한다.',10,NULL,NULL),
('kbs',2025,1,38,'multiple','다음 중 문장 성분의 호응이 자연스러운 것은?','["내가 하고 싶은 말은 끝까지 최선을 다하자.", "이 제품은 가격이 싸고 품질이 뛰어나다.", "그는 결코 이번 시험에 합격할 것이다.", "왜냐하면 그가 밤늦게까지 열심히 노력했다.", "그는 여간한 노력으로 마침내 목표를 이루었다."]'::jsonb,'2','주어와 서술어, 대등한 성분들이 자연스럽게 호응하는 문장은 ''가격이 싸고 품질이 뛰어나다''이다. 나머지는 ''~말은 ~다하자는 것이다'', ''결코 ~아니다'', ''왜냐하면 ~때문이다'', ''여간 ~아니다''처럼 호응이 맞지 않는다.',10,NULL,NULL),
('kbs',2025,1,39,'multiple','다음 중 높임법의 사용이 옳은 것은?','["주문하신 음료가 나오셨습니다.", "문의하신 상품은 지금 품절이십니다.", "이 넥타이가 손님께 참 잘 어울리십니다.", "손님, 이쪽으로 오시겠어요?", "사장님의 말씀이 계시겠습니다."]'::jsonb,'4','높임의 대상인 ''손님''을 주체 높임 선어말 어미 ''-시-''로 바르게 높인 ''오시겠어요''가 옳다. 나머지는 ''음료'', ''상품'', ''넥타이'' 같은 사물을 높이거나(''나왔습니다'', ''품절입니다'', ''어울립니다''), ''말씀이 있으시겠습니다''로 고쳐야 하는 잘못된 높임이다.',10,NULL,NULL),
('kbs',2025,1,40,'multiple','다음 중 중의적으로 해석되지 않는 문장은?','["나는 형과 동생을 온종일 찾아다녔다.", "귀여운 그녀의 강아지를 오래도록 바라보았다.", "나는 시장에서 사과 두 개와 배 한 개를 샀다.", "약속한 학생들이 다 오지 않았다.", "그는 지금 파란 넥타이를 매고 있다."]'::jsonb,'3','''사과 두 개와 배 한 개를 샀다''는 수량과 대상이 분명해 한 가지로만 해석된다. 나머지는 ''형과 함께/형까지 찾아다녔다'', ''귀여운 것이 그녀인지 강아지인지'', ''전부 안 왔는지 일부만 왔는지'', ''매는 동작 중인지 맨 상태인지''처럼 두 가지로 해석되는 중의적 표현이다.',10,NULL,NULL),
('kbs',2025,1,41,'multiple','다음 중 번역 투에서 벗어난 자연스러운 우리말 표현은?','["이 문제는 마침내 학생들에 의해 해결되었다.", "우리는 어제 오후에 긴 회의를 가졌다.", "나는 점심을 먹은 뒤 그와 함께 도서관에 갔다.", "어떤 일이든 성공은 꾸준한 노력을 필요로 한다.", "그의 성실함은 아무리 강조해도 지나치지 않다."]'::jsonb,'3','''그와 함께 도서관에 갔다''는 번역 투가 없는 자연스러운 우리말이다. 나머지는 ''학생들이 해결했다'', ''회의를 했다'', ''노력이 필요하다'', ''매우 중요하다''처럼 다듬어야 하는 번역 투(피동 남용, have 구문, need 구문, cannot be overemphasized)이다.',10,NULL,NULL),
('kbs',2025,1,42,'multiple','다음 중 밑줄 친 부분의 맞춤법이 옳은 것은?','["정말 오랫만에 옛 친구를 다시 만났다.", "왠지 오늘은 좋은 일이 생길 것 같다.", "시험이 생각보다 문안하게 끝나 다행이다.", "그 상황이 너무 어의없어 말문이 막혔다.", "그는 밤새 곰곰히 앞날을 생각했다."]'::jsonb,'2','''왠지''는 ''왜인지''가 줄어든 말로 바른 표기이다(''웬''은 ''웬일, 웬만큼''에 쓰임). 나머지는 ''오랜만에'', ''무난하게'', ''어이없어'', ''곰곰이''로 고쳐야 한다.',10,NULL,NULL),
('kbs',2025,1,43,'multiple','다음 중 밑줄 친 단어의 표준 발음이 옳지 않은 것은?','["봄이 되니 꽃잎[꼰닙]이 흐드러지게 피었다.", "그는 나의 맏형[마텽]이자 든든한 버팀목이다.", "눈길을 밟는[밤ː는] 소리가 정겹게 들린다.", "담을 넓히다[널피다] 이웃과 다투게 되었다.", "색연필[새견필]로 그림을 색칠하며 놀았다."]'::jsonb,'5','''색연필''은 합성어로 ''ㄴ'' 첨가와 비음화가 일어나 [생년필]로 발음되므로 [새견필]은 틀린 발음이다. ''꽃잎''은 [꼰닙], ''맏형''은 자음 축약으로 [마텽], ''밟는''은 [밤ː는], ''넓히다''는 자음 축약으로 [널피다]가 모두 옳다.',10,NULL,NULL),
('kbs',2025,1,44,'multiple','다음 중 띄어쓰기가 옳지 않은 것은?','["너무 힘들어서 남은 밥을 먹어 버렸다.", "나는 예전에 그를 한번 본 적이 있다.", "그는 아침으로 사과 한 개를 먹었다.", "이 사안은 김철수부장님께 먼저 보고했다.", "나는 지금 오직 최선을 다할 뿐이다."]'::jsonb,'4','직위나 직함을 나타내는 ''부장님''은 성명과 띄어 써야 하므로 ''김철수 부장님''이 옳다. 보조 용언 ''먹어 버렸다'', 의존 명사 ''적'', 단위 명사 ''개'', 의존 명사 ''뿐''의 띄어쓰기는 모두 바르다.',10,NULL,NULL),
('kbs',2025,1,45,'multiple','다음 중 어법에 맞는 문장은?','["그 아픈 기억은 좀처럼 잊혀지지 않는다.", "이 책은 지금도 많은 사람에게 읽혀진다.", "앞으로 좋은 결과가 있을 것으로 보여진다.", "회의에서 새로운 안건이 신중하게 다루어졌다.", "바람이 불자 열려 있던 문이 저절로 닫혀졌다."]'::jsonb,'4','''다루어졌다''는 ''다루다''에 피동 표현 ''-어지다''가 한 번만 붙은 올바른 피동이다. 나머지는 ''잊히지(잊+히+어지-)'', ''읽힌다'', ''보인다'', ''닫혔다''처럼 피동 접미사와 ''-어지다''가 겹친 이중 피동으로 어법에 맞지 않는다.',10,NULL,NULL),
('kbs',2025,1,46,'multiple','''지역 화폐 활성화 방안''이라는 주제로 글을 쓰기 위해 세운 글쓰기 계획으로 적절하지 않은 것은?','["예상 독자를 지역 소상공인과 주민으로 설정하여 실생활과 연결된 사례를 제시한다.", "지역 화폐의 개념과 도입 배경을 앞부분에 두어 독자의 이해를 돕는다.", "설문 자료와 통계를 인용해 주장의 객관성을 확보한다.", "지역 화폐의 문제점만을 집중적으로 다루어 부정적 인식을 강화한다.", "결론에서 실천 가능한 개선 방안을 구체적으로 제안한다."]'::jsonb,'4','주제가 ''활성화 방안''이므로 문제점만 집중적으로 다루어 부정적 인식을 강화하는 것은 글의 목적과 어긋난다. 문제점은 개선 방안 제시를 위한 근거로만 활용해야 한다.',10,NULL,NULL),
('kbs',2025,1,47,'multiple','''청소년 수면 부족''에 관한 글을 쓰기 위해 수집한 자료의 활용 방안으로 적절하지 않은 것은?

(가) 청소년의 하루 평균 수면 시간이 6시간으로 권장 시간에 미치지 못한다는 조사 통계
(나) 수면 부족이 집중력과 기억력 저하를 유발한다는 의학 연구 결과
(다) 늦은 시간까지 스마트폰을 사용하는 청소년의 인터뷰
(라) 특정 연예인이 하루 4시간만 잔다는 방송 발언','["(가)를 활용해 청소년 수면 부족의 실태를 객관적으로 제시한다.", "(나)를 활용해 수면 부족이 초래하는 부정적 영향을 뒷받침한다.", "(다)를 활용해 수면 부족의 구체적 원인을 사례로 제시한다.", "(라)를 활용해 짧은 수면이 바람직하다는 근거로 삼는다.", "(가)와 (나)를 연결해 실태와 그 영향을 논리적으로 전개한다."]'::jsonb,'4','(라)는 개인의 특수한 사례이자 주제와 상반되는 내용으로, 짧은 수면이 바람직하다는 근거로 삼으면 글의 주장을 훼손한다. 근거로서의 대표성과 타당성이 없다.',10,NULL,NULL),
('kbs',2025,1,48,'multiple','다음은 ''반려동물 유기 문제''에 관한 글의 개요이다. 개요를 수정·보완하기 위한 방안으로 적절하지 않은 것은?

[개요]
Ⅰ. 서론: 반려동물 유기의 실태
Ⅱ. 본론
  1. 유기의 원인
    가. 충동적 입양
    나. 양육 정보 부족
  2. 유기가 초래하는 문제
    가. 동물 복지 침해
    나. 반려동물 시장의 성장
  3. 유기 문제 해결 방안
    가. 입양 전 교육 의무화
Ⅲ. 결론: 책임 있는 반려 문화 정착 촉구','["''Ⅱ-2-나''는 상위 항목과 관련이 없으므로 삭제한다.", "''Ⅱ-3''에 ''유기 동물 보호소 지원 확대'' 항목을 추가해 방안을 보강한다.", "''Ⅱ-1''과 ''Ⅱ-3''이 대응되도록 원인별 해결 방안을 균형 있게 제시한다.", "서론에 유기 문제의 심각성을 보여 주는 통계를 추가한다.", "''Ⅱ-2-가''를 ''반려동물 등록제 도입''으로 교체해 논지를 강화한다."]'::jsonb,'5','''Ⅱ-2-가 동물 복지 침해''는 유기가 초래하는 문제로서 상위 항목에 부합하는 적절한 내용이다. 이를 해결 방안에 해당하는 ''반려동물 등록제 도입''으로 교체하면 항목 간 논리적 위계가 어긋난다.',10,NULL,NULL),
('kbs',2025,1,49,'multiple','다음 글에서 문단의 통일성을 해쳐 삭제해야 할 문장은?

걷기는 특별한 장비 없이 누구나 할 수 있는 운동이다. ㉠꾸준히 걸으면 심폐 지구력이 향상되고 혈액 순환이 원활해진다. ㉡또한 걷는 동안 뇌에 산소가 충분히 공급되어 스트레스 해소에도 도움이 된다. ㉢걷기는 관절에 무리를 주지 않아 노년층에게도 권장된다. ㉣최근에는 등산을 즐기는 인구가 늘면서 관련 용품 시장도 크게 성장하고 있다. ㉤이처럼 걷기는 몸과 마음의 건강을 함께 지켜 주는 유익한 운동이다.','["㉠", "㉡", "㉢", "㉣", "㉤"]'::jsonb,'4','이 문단의 중심 내용은 ''걷기의 유익함''이다. ㉣은 등산 용품 시장의 성장을 다루어 문단의 중심 화제에서 벗어나므로 통일성을 위해 삭제해야 한다.',10,NULL,NULL),
('kbs',2025,1,50,'multiple','밑줄 친 부분을 고쳐 쓴 것으로 적절하지 않은 것은?

환경 보호는 미래 세대를 위한 우리의 ㉠의무로서 반드시 실천해야 한다. 그러나 많은 사람들이 그 ㉡중요성을 알면서도 실천에 옮기지 못한다. 이는 개인의 노력만으로는 ㉢한계가 있기 때문이다. 따라서 정부와 기업이 ㉣적극적으로 나서서 제도적 뒷받침을 ㉤해야 될 것이다.','["㉠: 조사의 쓰임이 어색하므로 ''의무이므로''로 고친다.", "㉡: 문맥에 맞지 않으므로 ''심각성''으로 바꾼다.", "㉢: 의미를 분명히 하기 위해 ''한계가 있을 수밖에 없기''로 다듬는다.", "㉣: 자연스러운 표현을 위해 ''적극적으로''를 유지한다.", "㉤: 군더더기 표현이므로 ''해야 할 것이다''로 고친다."]'::jsonb,'2','㉡ ''중요성''은 앞뒤 문맥(''알면서도 실천하지 못한다'')과 자연스럽게 이어지므로 고칠 필요가 없다. ''심각성''으로 바꾸면 오히려 문맥이 어색해진다. 나머지는 조사·군더더기 등을 다듬은 적절한 고쳐쓰기이다.',10,NULL,NULL),
('kbs',2025,1,51,'multiple','다음 유비 추론의 빈칸에 들어갈 말로 가장 적절한 것은?

뿌리가 튼튼해야 나무가 거센 바람에도 쓰러지지 않듯이, ( )','["화려한 꽃일수록 향기가 진하기 마련이다.", "기초가 탄탄해야 어떤 시련에도 흔들리지 않는다.", "나무는 계절에 따라 잎의 색을 바꾼다.", "숲이 우거지면 많은 동물이 깃들어 산다.", "열매는 익을수록 아래로 고개를 숙인다."]'::jsonb,'2','''뿌리:나무''의 관계는 ''기초:대상''의 관계로 유비된다. 뿌리가 튼튼해야 바람에 견디듯, 기초가 탄탄해야 시련에 흔들리지 않는다는 논리가 대응하므로 ②가 적절하다.',10,NULL,NULL),
('kbs',2025,1,52,'multiple','다음 조건을 모두 충족하는 문장으로 가장 적절한 것은?

[조건]
① ''독서''의 가치를 강조할 것
② 비유적 표현을 사용할 것
③ 대구의 형식을 갖출 것','["책을 읽으면 지식이 쌓이고 생각이 넓어진다.", "독서는 마음의 양식이니 꾸준히 읽어야 한다.", "책은 마음을 밝히는 등불이요, 독서는 생각을 여는 열쇠이다.", "가을은 독서의 계절이므로 책을 많이 읽자.", "좋은 책 한 권은 훌륭한 스승과도 같다."]'::jsonb,'3','③은 ''책은 ~ 등불이요''와 ''독서는 ~ 열쇠이다''가 비유(등불, 열쇠)와 대구의 형식을 모두 갖추면서 독서의 가치를 강조한다. ⑤는 비유는 있으나 대구가 없고, ②는 비유는 있으나 대구가 없다.',10,NULL,NULL),
('kbs',2025,1,53,'multiple','''에너지 절약''을 주제로 한 표어로 가장 적절한 것은?','["에너지는 소중하니 모두 함께 노력하자.", "끄고 나온 불빛 하나, 밝아지는 우리 미래.", "전기 요금이 많이 나오면 가계에 부담이 된다.", "여름에는 에어컨을 적절히 사용하는 것이 좋다.", "에너지 절약은 국가 경제에 도움이 되는 일이다."]'::jsonb,'2','표어는 간결한 운율과 대비를 통해 강한 인상을 남겨야 한다. ②는 ''끄고 나온 불빛 하나''와 ''밝아지는 우리 미래''가 대구를 이루고 함축적이어서 표어로 가장 적절하다. 나머지는 설명적 서술에 그친다.',10,NULL,NULL),
('kbs',2025,1,54,'multiple','다음 광고 문구 중 ''청유형''과 ''비유''를 함께 사용하여 헌혈 참여를 권하는 것으로 가장 적절한 것은?','["헌혈은 생명을 살리는 고귀한 나눔입니다.", "당신의 붉은 마음, 누군가에겐 봄이 됩니다.", "따뜻한 피 한 방울, 생명의 씨앗을 함께 심어요.", "헌혈에 동참하면 많은 사람을 도울 수 있습니다.", "오늘도 수많은 환자가 피를 기다리고 있습니다."]'::jsonb,'3','③은 ''피 한 방울''을 ''생명의 씨앗''에 비유하고 ''심어요''라는 청유형 어미로 참여를 권하므로 두 조건을 모두 충족한다. ②는 비유는 있으나 청유형이 아니고, ①·④·⑤는 청유형과 비유가 함께 나타나지 않는다.',10,NULL,NULL),
('kbs',2025,1,55,'multiple','다음 표의 내용을 바탕으로 이끌어 낸 표현으로 적절하지 않은 것은?

[우리 지역 대중교통 이용 현황]
- 버스 이용률: 2020년 62% → 2024년 48%
- 자가용 이용률: 2020년 25% → 2024년 40%
- 도로 혼잡도: 2020년 대비 2024년 1.5배 증가','["버스 이용률이 감소하는 동안 자가용 이용률은 늘어났다.", "자가용 이용 증가가 도로 혼잡도 상승과 관련이 있어 보인다.", "대중교통 이용을 늘려 도로 혼잡을 줄일 필요가 있다.", "버스 이용률과 자가용 이용률은 서로 반대 방향으로 변화했다.", "도로 혼잡도가 낮아진 것은 버스 이용이 늘었기 때문이다."]'::jsonb,'5','표에 따르면 도로 혼잡도는 오히려 1.5배 증가했고 버스 이용률은 감소했다. ⑤는 자료의 수치와 정반대되는 진술이므로 적절하지 않다.',10,NULL,NULL),
('kbs',2025,1,56,'multiple','다음 상황을 나타내기에 가장 적절한 속담 또는 관용 표현은?

작은 문제를 미리 해결하지 않고 방치하다가, 나중에 훨씬 큰 손해를 보게 된 상황','["티끌 모아 태산", "호미로 막을 것을 가래로 막는다", "우물에 가 숭늉 찾는다", "달면 삼키고 쓰면 뱉는다", "가는 말이 고와야 오는 말이 곱다"]'::jsonb,'2','''호미로 막을 것을 가래로 막는다''는 작은 일에 미리 대처하지 않아 나중에 큰 힘을 들이게 됨을 뜻하므로 제시된 상황과 부합한다.',10,NULL,NULL),
('kbs',2025,1,57,'multiple','다음 조건을 모두 만족하는 ''숲 보호'' 캠페인 문구로 가장 적절한 것은?

[조건]
① 명령형이나 청유형을 피하고 평서형으로 표현할 것
② ''숲''을 사람에 빗대어 표현할 것','["숲을 지켜 맑은 공기를 되찾읍시다.", "숲은 말없이 우리에게 숨결을 나누어 주는 친구입니다.", "지금 당장 숲을 보호하세요.", "울창한 숲이 사라지면 우리도 힘들어집니다.", "나무 한 그루가 모여 큰 숲을 이룹니다."]'::jsonb,'2','②는 ''숨결을 나누어 주는 친구''로 숲을 사람에 빗대어(의인화) 표현하면서 평서형 문장으로 마무리하여 두 조건을 모두 충족한다. ①·③은 청유·명령형이고, ④·⑤는 의인화가 없다.',10,NULL,NULL),
('kbs',2025,1,58,'multiple','다음 유비 관계와 가장 유사한 것은?

나침반 : 방향 = ( ) : ( )','["온도계 : 유리", "지도 : 종이", "저울 : 무게", "시계 : 벽", "안경 : 렌즈"]'::jsonb,'3','''나침반:방향''은 ''측정·안내 도구:그 도구가 알려 주는 대상''의 관계이다. ''저울:무게'' 역시 저울이 무게를 알려 주는 도구이므로 관계가 동일하다. 나머지는 ''도구:재료'' 또는 ''도구:부속''의 관계이다.',10,NULL,NULL),
('kbs',2025,1,59,'multiple','다음은 ''노인 디지털 교육''에 관한 자료이다. 이를 재구성하여 표현한 문장으로 적절하지 않은 것은?

[자료]
- 65세 이상 인구 중 40%가 무인 주문기(키오스크) 사용에 어려움을 겪음
- 스마트폰 금융 서비스 이용률: 청년층 85%, 노년층 22%
- 노인 대상 디지털 교육 프로그램 참여 후 만족도 90%','["노년층 상당수가 일상 속 디지털 기기 사용에 불편을 느끼고 있다.", "금융 서비스 이용에서 세대 간 격차가 뚜렷하게 나타난다.", "디지털 교육 프로그램은 참여자들에게 높은 만족을 주었다.", "디지털 교육을 확대하면 정보 격차 해소에 도움이 될 수 있다.", "노년층의 금융 서비스 이용률이 청년층을 크게 앞지르고 있다."]'::jsonb,'5','자료에 따르면 노년층의 스마트폰 금융 서비스 이용률은 22%로 청년층 85%보다 훨씬 낮다. ⑤는 자료를 정반대로 해석한 것이므로 적절하지 않다.',10,NULL,NULL),
('kbs',2025,1,60,'multiple','다음 조건을 모두 충족하는 문장으로 가장 적절한 것은?

[조건]
① ''시간의 소중함''을 주제로 할 것
② 대구의 형식을 사용할 것
③ 격언이나 잠언과 같은 어조를 띨 것','["시간은 한 번 지나가면 다시 돌아오지 않는다.", "흘러간 시간은 강물과 같아서 붙잡을 수 없다.", "오늘을 아끼는 이는 내일을 얻고, 오늘을 버리는 이는 내일을 잃는다.", "우리는 늘 시간이 부족하다고 느끼며 살아간다.", "시간을 잘 관리하면 더 많은 일을 해낼 수 있다."]'::jsonb,'3','③은 ''오늘을 아끼는 이는 내일을 얻고''와 ''오늘을 버리는 이는 내일을 잃는다''가 대구를 이루며, 시간의 소중함을 격언적 어조로 표현하여 세 조건을 모두 충족한다. 나머지는 대구나 격언적 어조가 미흡하다.',10,NULL,NULL),
('kbs',2025,1,61,'multiple','이 시의 중심 정서로 가장 적절한 것은?','["떠나간 이에 대한 원망과 분노", "낡고 잊혀 가는 것에 대한 그리움과 애정", "미래에 대한 벅찬 기대와 설렘", "자연의 위대함 앞에서 느끼는 두려움", "도시 생활의 화려함에 대한 동경"]'::jsonb,'2','화자는 마을에서 잊혀 가는 ''늙은 우물''을 바라보며, 물을 긷던 사람들과 지난 시간을 떠올린다. ''마른 두레박에 여전히 남은 물비린내''와 ''나는 오래 그 곁에 머물렀다'' 등의 시구에서 낡고 사라져 가는 것에 대한 그리움과 따뜻한 애정이 중심 정서로 드러난다.',10,'늙은 우물

마을 끝 돌담 아래
이제는 아무도 찾지 않는 우물이 있다
이끼가 계단을 덮고
두레박은 마른 채 매달려 있지만

귀를 대면 아직도
깊은 데서 물소리가 걸어 나온다
어머니가 새벽마다 길어 올리던
그 차고 맑은 두레박 소리

동네 아이들의 웃음도
빨래하던 아낙의 방망이 소리도
이 둥근 입 속으로 떨어져
오래도록 잠겨 있을 것이다

마른 두레박에 여전히 남은
물비린내를 맡으며
나는 오래 그 곁에 머물렀다
사라지는 것들은 이렇게
한동안 제 냄새로 남는다',NULL),
('kbs',2025,1,62,'multiple','이 시의 표현상 특징으로 적절하지 않은 것은?','["청각적 심상을 활용하여 대상을 감각적으로 형상화하고 있다.", "우물을 사람처럼 표현하여 친근한 느낌을 자아내고 있다.", "과거의 장면을 떠올리는 방식으로 시상을 전개하고 있다.", "동일한 문장을 규칙적으로 반복하여 운율을 형성하고 있다.", "후각적 심상을 통해 사라지는 것의 여운을 드러내고 있다."]'::jsonb,'4','이 시는 ''물소리'', ''두레박 소리'', ''방망이 소리'' 등 청각적 심상(1)과 ''물비린내''라는 후각적 심상(5)을 활용한다. 우물을 ''둥근 입''으로 표현해 의인화하며(2), 어머니가 물을 긷던 과거 장면을 회상하는 방식으로 시상을 전개한다(3). 그러나 동일한 문장을 규칙적으로 반복하는 부분은 나타나지 않으므로 4가 적절하지 않다.',10,'늙은 우물

